  '1': { _id: '1', title: 'Kedarnath Trek', type: 'trekking', difficulty: 'challenging', destination: 'Kedarnath, Uttarakhand', duration: { days: 6, nights: 5 }, price: 12500, discountedPrice: 9999, coverImage: 'https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?w=1200&auto=format&fit=crop', gallery: ['https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?w=900&auto=format&fit=crop', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?w=900&auto=format&fit=crop', 'https://images.unsplash.com/photo-1585135497273-1a86b09fe70e?w=900&auto=format&fit=crop', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=900&auto=format&fit=crop'], ratingsAverage: 4.9, ratingsCount: 128, availableSeats: 8, altitude: '3,583 m', startLocation: 'Haridwar', endLocation: 'Haridwar', maxGroupSize: 12, description: 'One of the most sacred treks in India, the Kedarnath Trek leads you to the ancient Kedarnath Temple at 3,583 m — one of the 12 Jyotirlingas. This challenging yet spiritually enriching 14 km trek through the Garhwal Himalayas rewards trekkers with stunning alpine scenery, glacial rivers and a profound devotional energy felt nowhere else on Earth. The route passes through Junglechatti, Bhimbali and Lincholi before the final ascent to the sacred shrine.', highlights: ['Darshan at Kedarnath Jyotirlinga Temple', 'Trek through Himalayan alpine meadows', 'Cross the Chorabari Glacier trail', 'Sunrise over snow-capped Kedarnath Peak', 'Evening aarti at the ancient stone temple', 'Bhairavnath Temple exploration', 'Garhwali culture & local cuisine'], inclusions: ['Guest house accommodation throughout', 'All meals (breakfast & dinner)', 'Certified trek guide', 'Safety equipment & first-aid kit', 'Medical kit & oxygen cylinder', 'Transport from Haridwar & back'], exclusions: ['Flights/trains to Haridwar', 'Personal expenses', 'Travel insurance', 'Pony/helicopter charges', 'Lunch on trek days'], itinerary: [{ day: 1, title: 'Haridwar → Gaurikund', description: 'Drive 210 km to Gaurikund via Devprayag, Rudraprayag and Sonprayag. Check in and acclimatize. Evening puja at Gauri Temple.', accommodation: 'Guest House Gaurikund', meals: ['Dinner'] }, { day: 2, title: 'Gaurikund → Kedarnath (14 km Trek)', description: 'Early morning trek 14 km uphill through Junglechatti, Bhimbali and Lincholi to Kedarnath. Evening abhishek & aarti darshan at the Jyotirlinga.', accommodation: 'Guest House at Kedarnath', meals: ['Breakfast', 'Dinner'], distance: '14 km', altitude: '3,583 m' }, { day: 3, title: 'Kedarnath Temple & Bhairavnath', description: 'Full day for temple visits. Dawn abhishek puja, Bhairavnath Temple trek, Chorabari Tal (Gandhi Sarovar) visit. Afternoon meditation time.', accommodation: 'Guest House at Kedarnath', meals: ['Breakfast', 'Dinner'], altitude: '3,583 m' }, { day: 4, title: 'Kedarnath → Gaurikund (Descent)', description: 'Final darshan at sunrise. Descend 14 km back to Gaurikund. Rest & hot water soak.', accommodation: 'Guest House Gaurikund', meals: ['Breakfast', 'Dinner'], distance: '14 km' }, { day: 5, title: 'Gaurikund → Haridwar', description: 'Drive back to Haridwar. Evening at leisure on Har Ki Pauri ghats. Attend Ganga Aarti.', accommodation: 'Hotel Haridwar', meals: ['Breakfast'] }, { day: 6, title: 'Departure from Haridwar', description: 'Morning puja at Har Ki Pauri. Breakfast and departure. Trek concludes with cherished memories.', meals: ['Breakfast'] }] },

